"import json\nimport os\n\npath = r\"C:\\Users\\a-6600\\.gemini\\antigravity\\brain\\defefd3d-03a6-48cc-ab0b-1fbc66f83de5\\.system_generated\\logs\\transcript.jsonl\"\nwith open(path, \"r\", encoding=\"utf-8\") as f:\n    for idx, line in enumerate(f):\n        if idx >= 500:\n            continue\n        # Ignore recent search script outputs\n        if \"find_sql\" in line or \"Select-String\" in line:\n            continue\n        if \"CREATE TABLE\" in line or \"create table\" in line:\n            obj = json.loads(line)\n            print(f\"Line {idx}: step_index={obj.get('step_index')}, type={obj.get('type')}, source={obj.get('source')}, len={len(line)}\")\n            content = obj.get(\"content\", \"\")\n            if content:\n                safe_content = content[:100].encode('ascii', 'backslashreplace').decode('ascii')\n                print(f\"  Content snippet: {safe_content}\")\n            for tc in obj.get(\"tool_calls\", []):\n                args = tc.get(\"args\", {})\n                print(f\"  Tool call {tc.get('name')} to {args.get('TargetFile') or args.get('TargetFolder')}\")\n                code = args.get(\"CodeContent\") or args.get(\"ReplacementContent\")\n                if code:\n                    safe_code = code[:100].encode('ascii', 'backslashreplace').decode('ascii')\n                    print(f\"    Code snippet: {safe_code} ... (total {len(code)} chars)\")\n                    with open(f\"create_table_{idx}.txt\", \"w\", encoding=\"utf-8\") as outf:\n                        outf.write(code)\n"